import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.DbKnw1Aw.js";const u=JSON.parse('{"title":"自定义规则","description":"","frontmatter":{},"headers":[],"relativePath":"guide/custom-rules.md","filePath":"guide/custom-rules.md","lastUpdated":1794385075000}'),c={name:"guide/custom-rules.md"};function r(i,t,l,s,h,n){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="自定义规则" tabindex="-1">自定义规则 <a class="header-anchor" href="#自定义规则" aria-label="Permalink to &quot;自定义规则&quot;">​</a></h1><p>自定义规则用来处理分类之外的例外情况，分为两层：日常使用的<strong>快捷规则</strong>，以及默认折叠的<strong>高级规则</strong>。</p><h2 id="快捷规则" tabindex="-1">快捷规则 <a class="header-anchor" href="#快捷规则" aria-label="Permalink to &quot;快捷规则&quot;">​</a></h2><p>每一行包含一个动作、一种匹配方式和若干个值：</p><table tabindex="0"><thead><tr><th>选项</th><th>可选值</th></tr></thead><tbody><tr><td>动作</td><td>直连（<code>DIRECT</code>）、拒绝（<code>REJECT</code>）</td></tr><tr><td>匹配方式</td><td>域名、域名后缀、IP 段</td></tr></tbody></table><table tabindex="0"><thead><tr><th>匹配方式</th><th>含义</th><th>Clash</th><th>sing-box</th></tr></thead><tbody><tr><td>域名</td><td>完整域名精确匹配，不含子域名</td><td><code>DOMAIN</code></td><td><code>domain</code></td></tr><tr><td>域名后缀</td><td>该域名及其所有子域名</td><td><code>DOMAIN-SUFFIX</code></td><td><code>domain_suffix</code></td></tr><tr><td>IP 段</td><td>CIDR 网段</td><td><code>IP-CIDR</code></td><td><code>ip_cidr</code></td></tr></tbody></table><p>例如一行&quot;直连 + 域名后缀&quot;，填入 <code>example.com</code> 和 <code>example.org</code>，生成的 Clash 规则为：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DOMAIN-SUFFIX,example.com,DIRECT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DOMAIN-SUFFIX,example.org,DIRECT</span></span></code></pre></div><p>快捷规则直接指向内置的 <code>DIRECT</code> / <code>REJECT</code>，不会新建策略组。</p><h3 id="输入方式" tabindex="-1">输入方式 <a class="header-anchor" href="#输入方式" aria-label="Permalink to &quot;输入方式&quot;">​</a></h3><ul><li>多个值可以用逗号、中文逗号、空格或回车分隔，粘贴多行文本会自动拆分。</li><li>输入框为空时按退格键，删除最后一个值。</li></ul><h3 id="自动规范化" tabindex="-1">自动规范化 <a class="header-anchor" href="#自动规范化" aria-label="Permalink to &quot;自动规范化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输入</th><th>结果</th></tr></thead><tbody><tr><td><code>https://Foo.com/path?a=1</code></td><td><code>foo.com</code>（只保留主机名并转为小写）</td></tr><tr><td><code>*.example.com</code>（域名后缀）</td><td><code>example.com</code></td></tr><tr><td>中文域名</td><td>转换为 punycode（<code>xn--…</code>）</td></tr><tr><td><code>1.2.3.4</code>（IP 段）</td><td><code>1.2.3.4/32</code></td></tr><tr><td><code>2001:db8::1</code>（IP 段）</td><td><code>2001:db8::1/128</code></td></tr></tbody></table><h3 id="格式校验" tabindex="-1">格式校验 <a class="header-anchor" href="#格式校验" aria-label="Permalink to &quot;格式校验&quot;">​</a></h3><p>格式不正确的值会标红，行下方提示&quot;N 个值格式不正确，已忽略&quot;，<strong>这些值不会写入订阅</strong>。这样可以避免一个非法的 IP 段让整份 sing-box 配置加载失败。纯数字的顶级域（例如把 IP 填进了域名）也视为不合法。</p><h2 id="高级规则" tabindex="-1">高级规则 <a class="header-anchor" href="#高级规则" aria-label="Permalink to &quot;高级规则&quot;">​</a></h2><p>展开&quot;高级规则&quot;后，每条规则是一张完整的表单：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>出站</td><td>填新名称时，会新建同名策略组（成员包含节点选择、DIRECT、REJECT、自动选择和所有节点）；填 <code>DIRECT</code> / <code>REJECT</code> 时直接指向内置出站，不建组</td></tr><tr><td>Geo-Site</td><td>域名分类名，例如 <code>google</code>、<code>category-ai-!cn</code></td></tr><tr><td>Geo-IP</td><td>IP 分类名，例如 <code>private</code>、<code>cn</code>、<code>telegram</code></td></tr><tr><td>域名 / 域名后缀 / 域名关键词</td><td>对应 <code>DOMAIN</code> / <code>DOMAIN-SUFFIX</code> / <code>DOMAIN-KEYWORD</code></td></tr><tr><td>IP CIDR</td><td>IP 段</td></tr><tr><td>协议</td><td>仅 sing-box 生效，并且与同一条规则的其他条件是&quot;并且&quot;关系，建议单独成条</td></tr></tbody></table><p>高级规则会实时检查：</p><ul><li>出站名称重复，或与已有策略组同名（会导致客户端加载失败）；</li><li>Geo-Site 名称是否真实存在。名称不存在时标签标红：sing-box 会因为下载规则集失败而无法加载整份配置。</li><li>卡片底部显示这条规则会生成多少条 Clash 规则、指向哪里。</li></ul><h2 id="顺序与置顶" tabindex="-1">顺序与置顶 <a class="header-anchor" href="#顺序与置顶" aria-label="Permalink to &quot;顺序与置顶&quot;">​</a></h2><ul><li>生成时先输出快捷规则，再输出高级规则，各自保持界面上的顺序。</li><li>&quot;置顶&quot;开关默认打开：自定义规则排在所有分类规则之前，优先匹配。关闭后排在分类规则之后、<code>🐟 漏网之鱼</code> 之前。</li></ul>`,22)])])}const b=d(c,[["render",r]]);export{u as __pageData,b as default};
